/** Chance that a boss kill captures the boss as a companion (Assumption 23). */
export const CAPTURE_CHANCE = PROGRESSION_PARAMETERS.captureChance;
/**
 * Releases needed for one soul. 2 keeps the 30 min payout near +11 souls. The
 * measured effect on pacing is +0.16% kills over 100 seeds (an all-at-once
 * +10 souls control bounds it at +4.3%), well inside the ±5% budget.
 */
export const RELEASES_PER_SOUL = 2;

/** One companion volley per this many engine milliseconds (SPEC F35). */
export const COMPANION_ATTACK_MS = 1000;
/**
 * Extra swing delay per party rank (back → front) on top of the species'
 * attack delay, so even same-species members never land together (2026-09-06).
 */
export const PARTY_STAGGER_MS = 70;

export interface Engine {
  /** One input → one reducer step; returns the events it produced, in order. */
  attack(source: InputSource): GameEvent[];
  /**
   * Advance the engine clock by dtMs and emit what the clock produced
   * (non-finite/negative dt counts as 0). The ONLY way time moves forward.
   */
  tick(dtMs: number): GameEvent[];
  /** Run one roster/prestige action on the live state; `{ error }` → no events. */
  apply(a: CollectionAction): GameEvent[];
  getState(): Readonly<GameState>;
  toSave(): SaveFile;
}

/** Non-deterministic seed for production use; tests ALWAYS inject an Rng. */
function randomSeed(): number {
  return (Math.random() * 0x100000000) >>> 0;
}

/**
 * Every engine boots with fever cold (it is never persisted, SPEC F34).
 * ponytail: a placeholder — getState() always recomputes it from the clock,
 * so nothing inside the engine may read `state.fever`.
 */
const COLD_FEVER = { active: false, remainingMs: 0 };

const eligibleRareForState = (state: Readonly<GameState>) =>
  eligibleRareMonsters(discoveryContext(state, heroForm(state.hero?.equipped.formId ?? '')?.type));

/** Eligibility, independent of whether a species has already spawned or been killed. */
export const eligibleMonsterIds = (state: Readonly<GameState>): string[] =>
  [...COMMON_SPECIES_IDS, ...eligibleRareForState(state).map(monster => monster.id)];

/**
 * Save shapes are assumed well-formed here — tolerant parsing of untrusted
 * JSON is save.ts's parseSave(). The engine still clamps the resumed
 * monsterHp into [1n, maxHp] so a stale save can never spawn an already-dead
 * or over-healed monster.
 */
function initialState(save: SaveFileV3 | null, rng: Rng): GameState {
  if (!save) {
    const monster = randomMonster(0, rng);
    return {
      level: 1,
      xp: 0,
      killCount: 0,
      coins: 0,
      items: {},
      monster,
      monsterHp: monster.maxHp,
      companions: [],
      nextCompanionId: 1,
      souls: 0,
      releasedCount: 0,
      rebirths: 0,
      bestIndex: 0,
      pvpParty: [],
      fever: COLD_FEVER,
    };
  }
  const monster = monsterForIndex(save.monsterIndex, save.monsterSpeciesId);
  return {
    level: save.level,
    xp: save.xp,
    killCount: save.killCount,
    coins: save.coins,
    items: { ...save.items },
    monster,
    // Resume exactly, clamped into [1n, maxHp] so a stale save can never
    // spawn an already-dead or over-healed monster.
    monsterHp: clampHp(BigInt(save.monsterHp), monster.maxHp),
    companions: save.companions.map((c) => ({ ...c })),
    nextCompanionId: save.nextCompanionId,
    souls: save.souls,
    releasedCount: save.releasedCount ?? 0,
    rebirths: save.rebirths,
    bestIndex: Math.max(save.bestIndex, monster.index),
    pvpParty: [...save.pvpParty],
    fever: COLD_FEVER,
    ...(save.hero ? { hero: parseHeroProgress(save.hero) } : {}),
  };
}

/** Clamp a resumed hp into [1n, maxHp]. */
const clampHp = (hp: bigint, maxHp: bigint): bigint => (hp < 1n ? 1n : hp > maxHp ? maxHp : hp);

/** One independent, uniform species draw per spawn, including bosses. */
function randomMonster(index: number, rng: Rng): GameState['monster'] {
  return monsterForIndex(index, COMMON_SPECIES_IDS[Math.floor(rng.next() * COMMON_SPECIES_IDS.length)] ?? COMMON_SPECIES_IDS[0]);
}

/**
 * Create the game reducer. Every attack(source) call rolls a crit (one rng
 * draw), applies damage immediately, and on a kill rolls loot (rollLoot's own
 * draws), grants XP, levels up while the threshold is met (carry-over: the
 * threshold is subtracted), and spawns monster index+1 at full HP.
 *
 * Event order on a kill (SPEC F07/F33):
 * attack, monsterHit, monsterKilled, itemDropped[, bossCaptured][, levelUp...],
 * monsterSpawned.
 */
export function createEngine(
  save?: SaveFileV1 | SaveFileV2 | SaveFileV3 | null,
  rng: Rng = mulberry32(randomSeed()),
): Engine {
  const state = initialState(save ? upgradeSave(save) : null, rng);
  const savedProgress = save && 'progress' in save ? save.progress : undefined;
  state.progress = migrateProgress({ ...state, hero: state.hero ? { ...state.hero, choices: [] } : undefined,
    progress: save ? savedProgress : newProgress() }, state.monster.speciesId);
  if (state.hero) state.hero = parseHeroProgress(state.hero, discoveryContext(state, heroForm(state.hero.equipped.formId)?.type));
  for (const choice of state.hero?.choices ?? []) if (!state.progress.seenHeroes.includes(choice.formId)) state.progress.seenHeroes.push(choice.formId);
  // Open candidates remain seen history; migration acknowledges only actual acquisitions.
  /** The engine clock (Assumption 39) — advanced ONLY by tick(dtMs). */
  let clockMs = 0;
  let fever = createFever();
  const feverView = (): GameState['fever'] => ({
    active: feverActive(fever, clockMs),
    remainingMs: Math.max(0, fever.activeUntil - clockMs),
  });
  /** Next volley window start on the engine clock (SPEC F35). */
  let nextWindowMs = COMPANION_ATTACK_MS;
  /** Booked swings, in landing order: [at, companionId]. */
  let pending: { at: number; id: string }[] = [];

  /** One draw per spawn, split into conditional uniform pools. No extra draws on reload. */
  function spawn(index: number): void {
    const progress = state.progress!;
    const eligible = eligibleRareForState(state);
    const roll = Math.min(1 - Number.EPSILON, Math.max(0, rng.next()));
    let species: SpeciesId;
    if (eligible.length === 0) {
      species = COMMON_SPECIES_IDS[Math.floor(roll * COMMON_SPECIES_IDS.length)]!;
    } else {
      const chance = progress.lureRemaining > 0 ? 0.25 : 0.12;
      const forced = progress.rareMisses >= 11;
      const rare = forced || roll < chance;
      const pick = forced ? roll : rare ? roll / chance : (roll - chance) / (1 - chance);
      if (rare) {
        const unseen = eligible.filter((monster) => !progress.seenMonsters.includes(monster.id));
        const pool = unseen.length > 0 ? unseen : eligible;
        species = pool[Math.min(pool.length - 1, Math.floor(pick * pool.length))]!.id;
      } else species = COMMON_SPECIES_IDS[Math.min(COMMON_SPECIES_IDS.length - 1, Math.floor(pick * COMMON_SPECIES_IDS.length))]!;
      progress.rareMisses = rare ? 0 : progress.rareMisses + 1;
      if (progress.lureRemaining > 0) progress.lureRemaining--;
    }
    state.monster = monsterForIndex(index, species);
    state.monsterHp = state.monster.maxHp;
    if (!progress.seenMonsters.includes(species)) progress.seenMonsters.push(species);
  }

  /**
   * The one damage path: hero attacks and companion volleys both land here,
   * so a kill always chains identically — monsterKilled, loot, capture,
   * level-ups, then the next monster at full HP (SPEC F07/F33/F35).
   */
  function applyDamage(damage: bigint, events: GameEvent[]): void {
    state.monsterHp = state.monsterHp > damage ? state.monsterHp - damage : 0n;
    events.push({
      type: 'monsterHit',
      hpAfter: state.monsterHp,
      maxHp: state.monster.maxHp,
    });
    if (state.monsterHp !== 0n) return;

    const killed = state.monster;
    state.killCount += 1;
    const progress = state.progress!;
    progress.speciesKills[killed.speciesId] = Math.min(Number.MAX_SAFE_INTEGER, (progress.speciesKills[killed.speciesId] ?? 0) + 1);
    const xpGained = xpReward(killed.index) * (killed.boss ? BOSS_XP_MULT : 1);
    events.push({ type: 'monsterKilled', monster: { ...killed }, xpGained });

    const drops = rollLoot(rng, killed.index);
    // rollLoot always puts the coin first (loot.ts) — bosses pay 5x coins.
    const coin = drops[0];
    if (killed.boss && coin) {
      coin.amount *= BOSS_COIN_MULT;
    }
    for (const drop of drops) {
      if (drop.item.kind === 'coin') {
        state.coins += drop.amount;
      } else {
        state.items[drop.item.id] = (state.items[drop.item.id] ?? 0) + drop.amount;
      }
    }
    events.push({ type: 'itemDropped', drops });

    // One draw per boss kill, including a guaranteed first capture. nextCompanionId
    // records permanent acquisition, so emptying a roster never rearms the guarantee.
    const captureRoll = killed.boss ? rng.next() : 1;
    const firstCapture = PROGRESSION_PARAMETERS.firstCaptureBossIndex;
    const drew = killed.boss && (captureRoll < CAPTURE_CHANCE || firstCapture !== null &&
      state.nextCompanionId === 1 && killed.index >= firstCapture);
    if (drew && state.companions.length < ROSTER_CAP) {
      const companion: Companion = {
        id: `c${state.nextCompanionId++}`,
        speciesId: killed.speciesId,
        bossIndex: killed.index,
        level: 1,
        stars: 0,
      };
      state.companions.push(companion);
      events.push({ type: 'bossCaptured', companion: { ...companion } });
    } else if (drew) {
      // A full roster used to void the draw in silence. Release it instead:
      // every second release pays one soul, and the event says whether the
      // roster's weakest keeper was worth less than what just walked away.
      state.releasedCount += 1;
      const souls = state.releasedCount % RELEASES_PER_SOUL === 0 ? 1 : 0;
      state.souls += souls;
      const released = companionPower({ id: '', speciesId: killed.speciesId, bossIndex: killed.index, level: 1, stars: 0 });
      const weakest = state.companions.reduce(
        (min, c) => (companionPower(c) < min ? companionPower(c) : min), released);
      events.push({ type: 'companionReleased', speciesId: killed.speciesId, bossIndex: killed.index,
        souls, strongerThanWeakest: weakest < released });
    }

    state.xp += xpGained;
    while (state.xp >= xpToNext(state.level)) {
      state.xp -= xpToNext(state.level);
      state.level += 1;
      events.push({ type: 'levelUp', newLevel: state.level });
    }

    spawn(killed.index + 1);
    state.bestIndex = Math.max(state.bestIndex, state.monster.index);
    events.push({ type: 'monsterSpawned', monster: { ...state.monster } });
  }

  return {
    attack(source: InputSource): GameEvent[] {
      const events: GameEvent[] = [];

      // The input stamps the clock and may light fever BEFORE its own attack
      // event, so the 20th input already lands at x3 (SPEC F34).
      const lit = feverInput(fever, clockMs);
      fever = lit.fever;
      if (lit.started) events.push({ type: 'feverStart' });

      const crit = rng.next() < CRIT_CHANCE;
      const damage =
        trainedHeroPower(heroAttackPower(state.level, state.souls, state.hero?.reincarnations), state.progress?.trainingLevel) *
        (crit ? BigInt(CRIT_MULT) : 1n) *
        (feverActive(fever, clockMs) ? FEVER_MULT : 1n);
      events.push({ type: 'attack', damage, crit, source });
      applyDamage(damage, events);

      return events;
    },

    tick(dtMs: number): GameEvent[] {
      const dt = Number.isFinite(dtMs) && dtMs > 0 ? dtMs : 0;
      clockMs += dt;
      state.progress!.playTimeMs = Math.min(Number.MAX_SAFE_INTEGER, state.progress!.playTimeMs + dt);
      const events: GameEvent[] = [];
      // Swings landing inside this tick read fever as it stood when the tick began.
      if (state.hero && state.hero.deferRemainingMs > 0) {
        state.hero.deferRemainingMs = Math.max(0, state.hero.deferRemainingMs - dt);
        if (state.hero.deferRemainingMs === 0) events.push({ type: 'heroReady' });
      }
      if (state.hero && (state.hero.restRemainingMs ?? 0) > 0) {
        state.hero.restRemainingMs = Math.max(0, (state.hero.restRemainingMs ?? 0) - dt);
        if (state.hero.restRemainingMs === 0) events.push({ type: 'heroReady' });
      }
      const feverAtStart = fever;
      const cooled = feverTick(fever, clockMs);
      fever = cooled.fever;
      if (cooled.ended) events.push({ type: 'feverEnd' });

      // Companion volleys (SPEC F35; staggered since 2026-09-06): every
      // COMPANION_ATTACK_MS a window opens and books ONE swing per party member
      // at windowStart + the species' attack delay + PARTY_STAGGER_MS × rank.
      // Swings land in time order, each typed against the monster standing
      // there when it lands (F63) and tripled while fever burns at that moment.
      // The party is re-picked at every window: a capture, a fuse or the next
      // monster's type between windows changes who fights. Companions never crit.
      for (;;) {
        const due = pending[0]?.at ?? Number.POSITIVE_INFINITY;
        if (nextWindowMs <= clockMs && nextWindowMs <= due) {
          const windowStart = nextWindowMs;
          const booked = activeCompanions(state.companions, state.monster.type, state.hero?.equipped).map((c, rank) => ({
            at: windowStart + attackDelayOf(c.speciesId) + rank * PARTY_STAGGER_MS,
            id: c.id,
          }));
          pending = [...pending, ...booked].sort((a, b) => a.at - b.at);
          nextWindowMs += COMPANION_ATTACK_MS;
          continue;
        }
        if (due > clockMs) break;
        const fire = pending.shift();
        if (fire === undefined) break;
        const c = state.companions.find((x) => x.id === fire.id);
        if (c === undefined) continue; // consumed, fused or stolen since it was booked
        const mult = feverActive(feverAtStart, fire.at) ? FEVER_MULT : 1n;
        const attacker = typeOf(c.speciesId);
        const defender = state.monster.type;
        const damage = effectivePower(heroBuffedPower(companionPower(c), attacker, state.hero?.equipped), attacker, defender) * mult;
        events.push({
          type: 'companionAttack',
          companionId: c.id,
          speciesId: c.speciesId,
          damage,
          effectiveness: effectiveness(attacker, defender),
        });
        applyDamage(damage, events);
      }
      return events;
    },

    apply(a: CollectionAction): GameEvent[] {
      if (a.type === 'syncPvpProgress') {
        if ([a.wins, a.losses].every((value) => Number.isSafeInteger(value) && value >= 0)) {
          state.progress!.pvpWins = a.wins;
          state.progress!.pvpLosses = a.losses;
        }
        return [];
      }
      const previousLevel = state.level;
      const previousCoins = state.coins;
      const result = a.type === 'heroOffer' || a.type === 'heroChoose' || a.type === 'heroReroll' ||
        a.type === 'heroDefer' || a.type === 'heroEquip'
        ? applyHeroAction(state, a, rng) : a.type === 'shopBuy' ? applyEconomyAction(state, a) : applyCollection(state, a);
      if ('error' in result) return [];
      // applyCollection is total and copies everything; folding its fresh
      // state back in keeps engine-owned extras (fever) that it carried over.
      Object.assign(state, result.state);
      const progress = state.progress!;
      if (a.type === 'heroOffer' || a.type === 'heroReroll') {
        for (const choice of state.hero?.choices ?? []) if (!progress.seenHeroes.includes(choice.formId)) progress.seenHeroes.push(choice.formId);
      }
      if (a.type === 'heroReroll') progress.goldSpent = Math.min(Number.MAX_SAFE_INTEGER, progress.goldSpent + previousCoins - state.coins);
      if (a.type === 'heroChoose' && state.hero) recordReincarnation(progress, state.hero, previousLevel);
      if (a.type === 'rebirth' || a.type === 'heroChoose') {
        spawn(0);
      }
      return result.events;
    },

    getState(): Readonly<GameState> {
      return {
        ...state,
        fever: feverView(),
        monster: { ...state.monster },
        items: { ...state.items },
        companions: state.companions.map((c) => ({ ...c })),
        pvpParty: [...state.pvpParty],
        ...(state.hero ? { hero: copyHeroProgress(state.hero) } : {}),
        progress: copyProgress(state.progress!),
      };
    },

    toSave(): SaveFile {
      return {
        version: 3,
        level: state.level,
        xp: state.xp,
        killCount: state.killCount,
        coins: state.coins,
        items: { ...state.items },
        monsterIndex: state.monster.index,
        monsterSpeciesId: state.monster.speciesId as SpeciesId,
        monsterHp: String(state.monsterHp),
        companions: state.companions.map((c) => ({ ...c })),
        nextCompanionId: state.nextCompanionId,
        souls: state.souls,
        releasedCount: state.releasedCount,
        rebirths: state.rebirths,
        bestIndex: state.bestIndex,
        pvpParty: [...state.pvpParty],
        ...(state.hero ? { hero: copyHeroProgress(state.hero) } : {}),
        progress: copyProgress(state.progress!),
      };
    },
  };
}

// Save schema & tolerant parsing — SPEC F10/F29, Assumptions 7/21. Pure
// TypeScript, zero imports of electron/DOM/node. The app must never fail to
// boot because of a bad save: parseSave() NEVER throws — junk, missing and
// wrong-typed fields fall back per-field to DEFAULT_SAVE values. Disk always
// holds v3; older files are migrated on the way in (upgradeSave).

import { bigField } from './bignum.js';
import { monsterMaxHp } from './formulas.js';
import { isSpeciesId, SPECIES_IDS } from './monsters.js';
import type { SpeciesId } from './monsters.js';
import { heroForm, parseHeroProgress } from './hero.js';
import type { HeroProgress } from './hero.js';
import { discoveryContext, parseProgress } from './progress.js';
import type { Progress } from './progress.js';

/** Roster cap (GAME_DESIGN_V2 §2/§3); collection.ts owns the gameplay copy. */
const ROSTER_CAP = 30;

/** PvP party cap (GAME_DESIGN_V3 §3/§4); collection.ts owns the gameplay copy. */
const PARTY_CAP = 5;

/** A captured boss (GAME_DESIGN_V2 §2). Ids are minted from nextCompanionId. */
export interface Companion {
  /** 'c1', 'c2' … — deterministic, never a uuid. */
  id: string;
  /** SpeciesId of the captured boss. */
  speciesId: string;
  /** Global monster index it was captured at → base power. */
  bossIndex: number;
  /** Positive safe integer; no gameplay level cap. */
  level: number;
  stars: number;
}

/** Legacy save shape (v1). Accepted as input, never written. */
export interface SaveFileV1 {
  version: 1;
  level: number;
  /** XP into the current level. */
  xp: number;
  killCount: number;
  coins: number;
  /** Trinket id → count (positive integers only). */
  items: Record<string, number>;
  /** 0-based global index of the monster that was on screen. */
  monsterIndex: number;
  monsterHp: number;
}

/**
 * Persisted save-file schema, version 2. The engine's toSave() emits exactly
 * this shape; createEngine(save) resumes from it (SPEC F11/F29).
 */
export interface SaveFileV2 {
  version: 2;
  level: number;
  /** XP into the current level. */
  xp: number;
  killCount: number;
  coins: number;
  /** Trinket id → count (positive integers only). */
  items: Record<string, number>;
  /** 0-based global index of the monster that was on screen. */
  monsterIndex: number;
  /** Decimal digits, ≥ '1' — HP is unbounded (SPEC F30). */
  monsterHp: string;
  /** Captured bosses, at most ROSTER_CAP entries. */
  companions: Companion[];
  nextCompanionId: number;
  souls: number;
  rebirths: number;
  /** Deepest monsterIndex ever reached. */
  bestIndex: number;
}

/**
 * Persisted save-file schema, version 3: v2 plus the manually picked PvP-only
 * party (GAME_DESIGN_V3 §3). Empty = the auto party is used.
 */
export interface SaveFileV3 extends Omit<SaveFileV2, 'version'> {
  version: 3;
  /** Randomly selected current species; absent in legacy saves. */
  monsterSpeciesId?: SpeciesId;
  /** Companion ids, at most PARTY_CAP, all present in `companions`. */
  pvpParty: string[];
  /** Additive v0.4 extension; v1–v3 saves retain their progress unchanged. */
  hero?: HeroProgress;
  /** Additive v0.5 progress and v0.6 codex UI state; legacy fields keep their meanings. */
  progress?: Progress;
  /** Additive v0.4 extension; absent in older saves and read as 0. */
  releasedCount?: number;
}

/** The current schema. */
export type SaveFile = SaveFileV3;

/** Fresh-game values; also the per-field fallback for junk input. */
export const DEFAULT_SAVE: Readonly<SaveFileV3> = Object.freeze({
  version: 3 as const,
  level: 1,
  xp: 0,
  killCount: 0,
  coins: 0,
  items: Object.freeze({}) as Record<string, number>,
  monsterIndex: 0,
  monsterHp: String(monsterMaxHp(0)),
  companions: Object.freeze([] as Companion[]) as Companion[],
  nextCompanionId: 1,
  souls: 0,
  rebirths: 0,
  bestIndex: 0,
  pvpParty: Object.freeze([] as string[]) as string[],
  releasedCount: 0,
});

/**
 * Migrate a well-formed save to v3. v1 had no roster, souls or best depth;
 * v2 had no PvP party.
 */
export function upgradeSave(save: SaveFileV1 | SaveFileV2 | SaveFileV3): SaveFileV3 {
  if (save.version === 3) return { ...save, releasedCount: save.releasedCount ?? 0 };
  if (save.version === 2) return { ...save, version: 3, pvpParty: [], releasedCount: 0 };
  return {
    version: 3,
    level: save.level,
    xp: save.xp,
    killCount: save.killCount,
    coins: save.coins,
    items: { ...save.items },
    monsterIndex: save.monsterIndex,
    monsterHp: String(Math.max(1, Math.floor(save.monsterHp))),
    companions: [],
    nextCompanionId: 1,
    souls: 0,
    rebirths: 0,
    bestIndex: save.monsterIndex,
    pvpParty: [],
    releasedCount: 0,
  };
}

/**
 * Stable JSON: fixed top-level key order, items keys sorted, companions in
 * array order with fixed key order. Serializing the same logical save always
 * yields byte-identical text. Older input is upgraded first.
 */
export function serializeSave(save: SaveFileV1 | SaveFileV2 | SaveFileV3): string {
  const v3 = upgradeSave(save);
  const items: Record<string, number> = {};
  for (const id of Object.keys(v3.items).sort()) {
    items[id] = v3.items[id] ?? 0;
  }
  return JSON.stringify({
    version: 3,
    level: v3.level,
    xp: v3.xp,
    killCount: v3.killCount,
    coins: v3.coins,
    items,
    monsterIndex: v3.monsterIndex,
    monsterSpeciesId: v3.monsterSpeciesId,
    monsterHp: v3.monsterHp,
    companions: v3.companions.map((c) => ({
      id: c.id,
      speciesId: c.speciesId,
      bossIndex: c.bossIndex,
      level: c.level,
      stars: c.stars,
    })),
    nextCompanionId: v3.nextCompanionId,
    souls: v3.souls,
    rebirths: v3.rebirths,
    bestIndex: v3.bestIndex,
    pvpParty: v3.pvpParty,
    releasedCount: v3.releasedCount ?? 0,
    hero: parseHeroProgress(v3.hero),
    progress: parseProgress(v3.progress),
  });
}

/** Finite number → floored int clamped to `min`; anything else → fallback. */
function intField(value: unknown, fallback: number, min: number): number {
  if (typeof value !== 'number' || !Number.isFinite(value)) return fallback;
  return Math.max(min, Math.floor(value));
}

/** Integer in [min, max] — the companion fields have no fallback, they drop. */
function isInt(value: unknown, min: number, max = Number.MAX_SAFE_INTEGER): value is number {
  return typeof value === 'number' && Number.isInteger(value) && value >= min && value <= max;
}

/** Keep only entries whose count is a finite number that floors to ≥ 1. */
function itemsField(value: unknown): Record<string, number> {
  const items: Record<string, number> = {};
  if (typeof value !== 'object' || value === null || Array.isArray(value)) {
    return items;
  }
  for (const [id, count] of Object.entries(value)) {
    if (typeof count === 'number' && Number.isFinite(count) && Math.floor(count) >= 1) {
      items[id] = Math.floor(count);
    }
  }
  return items;
}

/**
 * Keep only fully valid companions (GAME_DESIGN_V2 §2): a bad entry is
 * dropped, it never defaults — a half-made companion would be worse than
 * none. Duplicate ids: first wins. At most ROSTER_CAP kept.
 */
function companionsField(value: unknown): Companion[] {
  const kept: Companion[] = [];
  if (!Array.isArray(value)) return kept;
  const seen = new Set<string>();
  for (const raw of value) {
    if (kept.length >= ROSTER_CAP) break;
    if (typeof raw !== 'object' || raw === null) continue;
    const c = raw as Record<string, unknown>;
    const id = c['id'];
    const speciesId = c['speciesId'];
    if (typeof id !== 'string' || id === '' || seen.has(id)) continue;
    if (typeof speciesId !== 'string' || !(SPECIES_IDS as readonly string[]).includes(speciesId)) {
      continue;
    }
    if (!isInt(c['bossIndex'], 0) || !isInt(c['level'], 1) || !isInt(c['stars'], 0)) continue;
    seen.add(id);
    kept.push({ id, speciesId, bossIndex: c['bossIndex'], level: c['level'], stars: c['stars'] });
  }
  return kept;
}

/**
 * Keep only ids that are really on the parsed roster (a party pointing at a
 * consumed companion would resurrect it), deduped first-wins, PARTY_CAP kept.
 */
function pvpPartyField(value: unknown, companions: Companion[]): string[] {
  if (!Array.isArray(value)) return [];
  const ids = new Set(companions.map((c) => c.id));
  return [...new Set(value.filter((id): id is string => typeof id === 'string' && ids.has(id)))]
    .slice(0, PARTY_CAP);
}

/**
 * Tolerant parse of untrusted save data (SPEC F10/F29). Accepts anything —
 * pre-parsed JSON values (what main's load-state hands over) or raw JSON
 * text — and NEVER throws. Every invalid field independently falls back to
 * its DEFAULT_SAVE value; the input `version` is ignored (the shape decides)
 * and the output is always v3. Range clamping beyond that (e.g. monsterHp vs
 * the monster's maxHp) is the engine's job. Always returns fresh objects.
 */
export function parseSave(raw: unknown): SaveFileV3 {
  let value: unknown = raw;
  if (typeof value === 'string') {
    try {
      value = JSON.parse(value);
    } catch {
      value = null;
    }
  }
  const record: Record<string, unknown> =
    typeof value === 'object' && value !== null && !Array.isArray(value)
      ? (value as Record<string, unknown>)
      : {};
  const companions = companionsField(record['companions']);
  const initialHero = parseHeroProgress(record['hero']);
  const progress = parseProgress(record['progress']);
  const hero = parseHeroProgress(initialHero, discoveryContext({
    killCount: intField(record['killCount'], 0, 0), hero: initialHero, progress, companions,
    ...(typeof record['monsterSpeciesId'] === 'string' ? { monsterSpeciesId: record['monsterSpeciesId'] } : {}),
  }, heroForm(initialHero?.equipped.formId ?? '')?.type));
  const species = record['monsterSpeciesId'];
  // Re-minting must never collide with an id already on the roster.
  let nextCompanionId = intField(record['nextCompanionId'], DEFAULT_SAVE.nextCompanionId, 1);
  for (const c of companions) {
    nextCompanionId = Math.max(nextCompanionId, Number(c.id.replace(/\D/g, '') || 0) + 1);
  }
  return {
    version: 3,
    level: intField(record['level'], DEFAULT_SAVE.level, 1),
    xp: intField(record['xp'], DEFAULT_SAVE.xp, 0),
    killCount: intField(record['killCount'], DEFAULT_SAVE.killCount, 0),
    coins: intField(record['coins'], DEFAULT_SAVE.coins, 0),
    items: itemsField(record['items']),
    monsterIndex: intField(record['monsterIndex'], DEFAULT_SAVE.monsterIndex, 0),
    ...(typeof species === 'string' && isSpeciesId(species) ? { monsterSpeciesId: species } : {}),
    monsterHp: (bigField(record['monsterHp']) ?? DEFAULT_SAVE.monsterHp).replace(/^0$/, '1'),
    companions,
    nextCompanionId,
    souls: intField(record['souls'], DEFAULT_SAVE.souls, 0),
    rebirths: intField(record['rebirths'], DEFAULT_SAVE.rebirths, 0),
    bestIndex: intField(record['bestIndex'], DEFAULT_SAVE.bestIndex, 0),
    pvpParty: pvpPartyField(record['pvpParty'], companions),
    releasedCount: intField(record['releasedCount'], 0, 0),
    ...(hero ? { hero } : {}),
    ...(progress ? { progress } : {}),
  };
}

// Companion collection — SPEC F32 (Assumptions 5/23/24/26; GAME_DESIGN_V2
// §4/§6). Pure TypeScript, zero imports of electron/DOM/node. Every export is
// total and never mutates its input: applyCollection returns fresh objects or
// an { error }, so the caller can apply it straight onto live engine state.

import { simulateBattle } from './battle.js';
import { monsterForIndex, sizeOf, typeOf } from './monsters.js';
import { monsterMaxHp } from './formulas.js';
import { effectivePower } from './types-chart.js';
import type { MonsterType } from './types-chart.js';
import type { BattleHeroes, Blow } from './battle.js';
import { heroBuffedPower } from './hero.js';
import type { HeroAction, HeroRoll } from './hero.js';
import type { EconomyAction } from './economy.js';
import { acquiredDiscoveries, isDiscoveryAction, migrateProgress } from './progress.js';
import type { DiscoveryAction } from './progress.js';
import type { Companion } from './save.js';
import type { Rng } from './rng.js';
import type { GameState, PvpResultAction } from './types.js';

/** Reincarnation unlocks here; companion growth has no gameplay level cap. */
export const COMPANION_REINCARNATION_LEVEL = 10;

/** How many companions fight together — field volley and PvP party (F61). */
export const PARTY_SIZE = 5;

/** Roster cap (save.ts keeps its own copy for parsing). */
export const ROSTER_CAP = 30;

/** Rebirth unlocks at this monster index (Assumption 5). */
export const REBIRTH_MIN_INDEX = 40;

/** Companion attack power (Assumption 24) — bigint, unbounded. */
export const companionPower = (c: Companion): bigint => {
  const base = monsterMaxHp(c.bossIndex) / 20n;
  return (base < 1n ? 1n : base) * BigInt(c.level) * 2n ** BigInt(c.stars);
};

export type CompanionSnapshot = Pick<Companion, 'speciesId' | 'bossIndex' | 'level' | 'stars'>;

/** Confirmation crosses IPC; reject malformed or imprecise counters before use. */
export function isCompanionSnapshot(value: unknown): value is CompanionSnapshot {
  if (!value || typeof value !== 'object') return false;
  const c = value as Record<string, unknown>;
  return typeof c['speciesId'] === 'string' && c['speciesId'].length > 0 &&
    Number.isSafeInteger(c['bossIndex']) && Number(c['bossIndex']) >= 0 &&
    Number.isSafeInteger(c['level']) && Number(c['level']) >= 1 &&
    Number.isSafeInteger(c['stars']) && Number(c['stars']) >= 0;
}

/** Exact preview: at Lv10 the reset retains one fifth of the previous power. */
export function companionReincarnationPreview(c: Companion):
  { level: 1; stars: number; beforePower: bigint; afterPower: bigint } | null {
  if (!isCompanionSnapshot(c) || c.level < COMPANION_REINCARNATION_LEVEL || !Number.isSafeInteger(c.stars + 1)) return null;
  return { level: 1, stars: c.stars + 1, beforePower: companionPower(c),
    afterPower: companionPower({ ...c, level: 1, stars: c.stars + 1 }) };
}

/** Numeric part of a 'cN' id — the tie-breaker (same rule as parseSave). */
const idNum = (id: string): number => Number(id.replace(/\D/g, '') || 0);

/** Descending bigint comparator. */
const desc = (a: bigint, b: bigint): number => (a === b ? 0 : b > a ? 1 : -1);

/**
 * The PARTY_SIZE best companions against `enemyType` (F61): effective power
 * desc, ties → higher raw power → lower numeric id. Without a type the raw
 * power decides, which is what the PvP default `autoParty` wants.
 */
export function activeCompanions(
  cs: readonly Companion[],
  enemyType?: MonsterType,
  hero?: HeroRoll,
): Companion[] {
  const power = (c: Companion): bigint => heroBuffedPower(companionPower(c), typeOf(c.speciesId), hero);
  const effective = (c: Companion): bigint =>
    enemyType === undefined
      ? power(c)
      : effectivePower(power(c), typeOf(c.speciesId), enemyType);
  return [...cs]
    .sort(
      (a, b) =>
        desc(effective(a), effective(b)) ||
        desc(companionPower(a), companionPower(b)) ||
        idNum(a.id) - idNum(b.id),
    )
    .slice(0, PARTY_SIZE);
}

/** The PvP default party: the PARTY_SIZE strongest by raw power. */
export function autoParty(cs: readonly Companion[], hero?: HeroRoll): Companion[] {
  return activeCompanions(cs, undefined, hero);
}

/** `ids` resolved against `cs` in the given order; unknown/duplicate dropped. */
function resolveIds(cs: readonly Companion[], ids: readonly string[]): Companion[] {
  const party: Companion[] = [];
  for (const id of ids) {
    if (party.length >= PARTY_SIZE) break;
    const c = cs.find((x) => x.id === id);
    if (c && !party.includes(c)) party.push(c);
  }
  return party;
}

/** The manual PvP party; an empty result falls back to `autoParty` (F61). */
export function pvpParty(cs: readonly Companion[], ids: readonly string[], hero?: HeroRoll): Companion[] {
  const party = resolveIds(cs, ids);
  return party.length > 0 ? party : autoParty(cs, hero);
}

/** Draw order of a party: biggest first (back row), ties keep party order. */
export function partyOrder(party: readonly Companion[]): Companion[] {
  return [...party].sort((a, b) => sizeOf(b.speciesId) - sizeOf(a.speciesId));
}

/**
 * Events produced here (GAME_DESIGN_V2 §6). T28 folds both variants into the
 * `GameEvent` union in types.ts; every other action returns no events.
 * ponytail: declared locally until then — types.ts is owned by T26/T28/T29.
 */
export type CollectionEvent =
  | { type: 'rebirth'; souls: number }
  | { type: 'pvpResolved'; won: boolean; stolen: Companion | null; lostId: string | null };

/** Every roster/prestige operation the menu and the net layer can request. */
export type CollectionAction =
  | HeroAction
  | EconomyAction
  | DiscoveryAction
  /** Main-origin absolute counters; never accepted from MENU_ACTION. */
  | { type: 'syncPvpProgress'; wins: number; losses: number }
  | { type: 'consume'; targetId: string; foodId: string }
  | { type: 'fuse'; aId: string; bId: string }
  | { type: 'reincarnate'; id: string; expected?: CompanionSnapshot }
  | { type: 'sacrifice'; id: string }
  | { type: 'rebirth' }
  | { type: 'addCompanion'; companion: Companion }
  | { type: 'removeCompanions'; ids: string[] }
  | { type: 'setPvpParty'; ids: string[] }
  | PvpResultAction;

export type CollectionResult =
  | { state: GameState; events: CollectionEvent[] }
  | { error: string };

/** Fresh roster: `dropIds` removed, `editId` replaced by `edit(c)`, rest copied. */
function reroster(
  cs: readonly Companion[],
  dropIds: readonly string[],
  editId?: string,
  edit?: (c: Companion) => Companion,
): Companion[] {
  return cs
    .filter((c) => !dropIds.includes(c.id))
    .map((c) => (edit && c.id === editId ? edit(c) : { ...c }));
}

/** Fresh state: nothing of `state` is shared with the result. */
function next(
  state: Readonly<GameState>,
  companions: Companion[],
  patch: Partial<GameState> = {},
  events: CollectionEvent[] = [],
): CollectionResult {
  return {
    state: {
      ...state,
      items: { ...state.items },
      monster: { ...state.monster },
      companions,
      ...patch,
    },
    events,
  };
}

/** Keep server transfer IDs so the theft ledger survives the next save/upload. */
function minted(
  companions: Companion[],
  nextCompanionId: number,
  c: Companion,
): Companion | null {
  if (companions.length >= ROSTER_CAP) return null;
  // Legacy/local callers still receive a fresh local ID; the server owns s/r IDs.
  const id = /^[sr][0-9a-f]+$/.test(c.id) ? c.id : `c${nextCompanionId}`;
  if (companions.some((existing) => existing.id === id)) return null;
  const fresh: Companion = { ...c, id };
  companions.push(fresh);
  return fresh;
}

/**
 * Apply one lifecycle action (Assumption 26). Total: an unknown action type,
 * an unknown/duplicate companion id or an unmet precondition yields
 * `{ error }` and the caller keeps its state; success yields a brand-new
 * state plus the events of GAME_DESIGN_V2 §6.
 */
export function applyCollection(
  state: Readonly<GameState>,
  action: CollectionAction,
): CollectionResult {
  const cs = state.companions;
  const find = (id: string): Companion | undefined => cs.find((c) => c.id === id);

  switch (action.type) {
    case 'acknowledgeDiscoveries':
    case 'setDiscoveryGoal': {
      if (!isDiscoveryAction(action)) return { error: 'discovery: invalid action' };
      const progress = migrateProgress(state, state.monster.speciesId);
      const codex = progress.codex!;
      if (action.type === 'setDiscoveryGoal') codex.goal = action.goal ? { kind: action.goal.kind, id: action.goal.id } : null;
      else {
        const acquired = acquiredDiscoveries({ ...state, progress });
        // A displayed snapshot can acknowledge only actually acquired entries.
        codex.acknowledgedHeroes = [...new Set([...codex.acknowledgedHeroes,
          ...action.heroes.filter((id) => acquired.heroes.includes(id))])];
        codex.acknowledgedMonsters = [...new Set([...codex.acknowledgedMonsters,
          ...action.monsters.filter((id) => acquired.monsters.includes(id))])];
      }
      return next(state, reroster(cs, []), { progress });
    }
    case 'consume': {
      const target = find(action.targetId);
      const food = find(action.foodId);
      if (!target || !food || target.id === food.id) return { error: 'consume: bad ids' };
      const level = target.level + 1 + food.stars;
      if (!Number.isSafeInteger(level) || level < 1) return { error: 'consume: level overflow' };
      return next(
        state,
        reroster(cs, [food.id], target.id, (c) => ({
          ...c,
          level,
        })),
      );
    }
    case 'fuse': {
      const a = find(action.aId);
      const b = find(action.bId);
      if (!a || !b || a.id === b.id) return { error: 'fuse: bad ids' };
      if (a.speciesId !== b.speciesId || a.stars !== b.stars) {
        return { error: 'fuse: needs the same species and stars' };
      }
      if (!Number.isSafeInteger(a.stars + 1)) return { error: 'fuse: stars overflow' };
      return next(
        state,
        reroster(cs, [b.id], a.id, (c) => ({
          ...c,
          bossIndex: Math.max(a.bossIndex, b.bossIndex),
          level: 1,
          stars: c.stars + 1,
        })),
      );
    }
    case 'reincarnate': {
      const c = find(action.id);
      if (!c) return { error: 'reincarnate: unknown id' };
      if (!Number.isSafeInteger(c.level) || c.level < COMPANION_REINCARNATION_LEVEL) return { error: 'reincarnate: needs level 10' };
      if (!Number.isSafeInteger(c.stars + 1)) return { error: 'reincarnate: stars overflow' };
      if (action.expected !== undefined && (!isCompanionSnapshot(action.expected) ||
        action.expected.speciesId !== c.speciesId || action.expected.bossIndex !== c.bossIndex ||
        action.expected.level !== c.level || action.expected.stars !== c.stars)) return { error: 'reincarnate: confirmation changed' };
      return next(
        state,
        reroster(cs, [], c.id, (x) => ({ ...x, level: 1, stars: x.stars + 1 })),
      );
    }
    case 'sacrifice': {
      const c = find(action.id);
      if (!c) return { error: 'sacrifice: unknown id' };
      const souls = state.souls + 1 + c.stars;
      if (!Number.isSafeInteger(souls)) return { error: 'sacrifice: souls overflow' };
      return next(state, reroster(cs, [c.id]), { souls });
    }
    case 'rebirth': {
      if (state.monster.index < REBIRTH_MIN_INDEX) {
        return { error: `rebirth: needs monster index ${REBIRTH_MIN_INDEX}` };
      }
      const souls = state.souls + Math.floor(state.monster.index / 8);
      const first = monsterForIndex(0);
      return next(
        state,
        reroster(cs, []),
        {
          level: 1,
          xp: 0,
          monster: first,
          monsterHp: first.maxHp,
          souls,
          rebirths: state.rebirths + 1,
        },
        [{ type: 'rebirth', souls }],
      );
    }
    case 'addCompanion': {
      const companions = reroster(cs, []);
      if (!minted(companions, state.nextCompanionId, action.companion)) {
        return { error: 'addCompanion: roster is full or id already exists' };
      }
      return next(state, companions, { nextCompanionId: state.nextCompanionId + 1 });
    }
    case 'removeCompanions':
      return next(state, reroster(cs, action.ids));
    case 'setPvpParty':
      // Never an error and no event: an all-unknown list just empties it.
      return next(state, reroster(cs, []), {
        pvpParty: resolveIds(cs, action.ids).map((c) => c.id),
      });
    case 'pvpResult': {
      if (action.stolen && /^[sr][0-9a-f]+$/.test(action.stolen.id) && cs.some((c) => c.id === action.stolen!.id)) {
        return { error: 'pvpResult: transferred id already exists' };
      }
      const companions = reroster(cs, action.lostId === null ? [] : [action.lostId]);
      // A steal into a full roster is void, never an error (Assumption 23).
      const stolen = action.stolen && minted(companions, state.nextCompanionId, action.stolen);
      return next(
        state,
        companions,
        { nextCompanionId: state.nextCompanionId + (stolen ? 1 : 0) },
        [
          {
            type: 'pvpResolved',
            won: action.won,
            stolen: stolen ?? null,
            lostId: action.lostId,
          },
        ],
      );
    }
    default:
      return { error: 'unknown action' };
  }
}

/** Chance an attacking win also carries a companion home (GAME_DESIGN_V3 §5). */
export const STEAL_CHANCE = 0.15;

/**
 * Resolve one asynchronous PvP exchange (SPEC F37; GAME_DESIGN_V3 §5). The
 * verdict and the blow list come from the seedless `simulateBattle`; the rng
 * only decides the loot. Shared byte-for-byte with the server, which calls it
 * with `mulberry32(seed)` and moves `moved` between the stored rosters — so
 * exactly 2 draws happen per call, the victim draw included even when nobody
 * can be stolen, and the client can replay the same match from the seed.
 * Only the attacker ever steals: a losing attacker keeps its whole roster.
 * ponytail: `attackerRosterSize` defaults to the party size so the v2 3-arg
 * call still compiles; T60 passes the real roster length.
 */
export function resolvePvp(
  attacker: readonly Companion[],
  defender: readonly Companion[],
  rng: Rng,
  attackerRosterSize = attacker.length,
  heroes: BattleHeroes = {},
): { attackerWon: boolean; moved: Companion | null; blows: Blow[] } {
  const { attackerWon, blows } = simulateBattle(attacker, defender, heroes);
  const stealRoll = rng.next() < STEAL_CHANCE;
  const victim = defender[Math.floor(rng.next() * defender.length)] ?? null;
  return {
    attackerWon,
    moved: attackerWon && stealRoll && attackerRosterSize < ROSTER_CAP ? victim : null,
    blows,
  };
}

